<script>
$(function(){
 const canManage=@json(auth()->user()->can('finished-goods.create')||auth()->user()->can('finished-goods.update'));
 const modal=canManage?new bootstrap.Modal(document.getElementById('finishedModal')):null, moModal=canManage?new bootstrap.Modal(document.getElementById('finishedMoModal')):null;
 const table=$('#finishedTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:{url:@json(route('super.finished-goods.dt')),data:d=>{d.from_date=$('#finishedFrom').val();d.to_date=$('#finishedTo').val()}},columns:[{data:'DT_RowIndex',orderable:false,searchable:false},{data:'actions',orderable:false,searchable:false,className:'text-nowrap'},{data:'finished_goods_number',name:'finished_goods_number'},{data:'date',name:'processed_at',render:d=>d?new Date(d+'T00:00:00').toLocaleDateString():''},{data:'style',orderable:false,searchable:false},{data:'item_code',orderable:false,searchable:false},{data:'item_name',orderable:false,searchable:false},{data:'input_quantity',className:'text-end'},{data:'good_quantity',className:'text-end'},{data:'mo',orderable:false,searchable:false},{data:'po_buyer',orderable:false,searchable:false}],order:[[3,'desc']],drawCallback:()=>window.feather&&feather.replace()});
 $('#finishedFilter').on('click',()=>table.ajax.reload());$('#finishedExport').on('click',function(e){e.preventDefault();const q=new URLSearchParams();if($('#finishedFrom').val())q.set('from_date',$('#finishedFrom').val());if($('#finishedTo').val())q.set('to_date',$('#finishedTo').val());location.href=this.href+'?'+q.toString()});
 if(!canManage)return;
 const moTable=$('#finishedMoTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:@json(route('super.finished-goods.orders.dt')),columns:[{data:'number'},{data:'buyer_po_number'},{data:'style',orderable:false,searchable:false},{data:'item_code',orderable:false,searchable:false},{data:'item_name',orderable:false,searchable:false},{data:'available_packing_quantity',className:'text-end'},{data:'actions',orderable:false,searchable:false}]});
 function reset(){document.getElementById('finishedForm').reset();$('#finishedId,#finishedMoId').val('');$('#finishedDate').val(@json(now()->toDateString()));$('#finishedNumber,#finishedMoLabel,#finishedStyle,#finishedCode,#finishedName,#finishedUnit,#finishedPo').val('');$('#saveFinished').text(@json(__('ui.common.save')));}
 $('#addFinished').on('click',function(){reset();$.get(@json(route('super.finished-goods.number-preview'))).done(x=>$('#finishedNumber').val(x.number));moModal.show()});$('#chooseFinishedMo').on('click',()=>moModal.show());
 $(document).on('click','.js-select-finished-mo',function(){const b=$(this);$('#finishedMoId').val(b.data('id'));$('#finishedMoLabel').val(b.data('no'));$('#finishedStyle').val(b.data('style'));$('#finishedCode').val(b.data('code'));$('#finishedName').val(b.data('name'));$('#finishedUnit').val(b.data('unit'));$('#finishedPo').val(b.data('po'));$('#receivePacking').attr('max',b.data('available'));moModal.hide();modal.show()});
 $('#finishedForm').on('submit',function(e){e.preventDefault();const id=$('#finishedId').val(),url=id?@json(route('super.finished-goods.update',['entry'=>'__ID__'])).replace('__ID__',id):@json(route('super.finished-goods.store'));$.ajax({url,method:id?'PUT':'POST',data:$(this).serialize()}).done(x=>{modal.hide();table.ajax.reload(null,false);Swal.fire({icon:'success',text:x.message})}).fail(x=>Swal.fire({icon:'error',text:Object.values(x.responseJSON?.errors||{}).flat().join('\n')||x.responseJSON?.message||'Error'}))});
 $(document).on('click','.js-edit-finished',function(){const b=$(this);reset();$('#finishedId').val(b.data('id'));$('#finishedNumber').val(b.data('no'));$('#finishedDate').val(b.data('date'));$('#finishedMoId').val(b.data('mo'));$('#finishedMoLabel').val(b.data('mo-number'));$('#finishedStyle').val(b.data('style'));$('#finishedCode').val(b.data('code'));$('#finishedName').val(b.data('name'));$('#finishedUnit').val(b.data('unit'));$('#finishedPo').val(b.data('po'));$('#receivePacking').val(b.data('received'));$('#finishedQty').val(b.data('good'));$('#saveFinished').text(@json(__('ui.common.save_changes')));modal.show()});
 $(document).on('click','.js-delete-finished',function(){const id=$(this).data('id');Swal.fire({icon:'warning',title:@json(__('ui.common.confirm_delete')),showCancelButton:true,confirmButtonText:@json(__('ui.common.delete')),cancelButtonText:@json(__('ui.common.cancel'))}).then(r=>{if(r.isConfirmed)$.ajax({url:@json(route('super.finished-goods.destroy',['entry'=>'__ID__'])).replace('__ID__',id),method:'DELETE',data:{_token:@json(csrf_token())}}).done(x=>{table.ajax.reload(null,false);Swal.fire({icon:'success',text:x.message})}).fail(x=>Swal.fire({icon:'error',text:x.responseJSON?.message||'Error'}))})});
});
</script>
